A=h*h/(8*me)*(3/pi)**(2/3)/e
D=8*pi*sqrt(2)*me**1.5/h**3*e**1.5
rows=[]
def N(label,a,u,why,t=None,**kw):
 p=dict(label=label,type='numeric',answer=a,unit=u,tolerance=max(abs(a)*.008,1e-300) if t is None else t,explanation=why);p.update(kw);return p
def C(label,a,b,d,why):return dict(label=label,type='choice',answer=a,options=[a,b,d],explanation=why)
def R(n,parts,why,kind='problems',pages=None,assumptions=None,scope=None,**kw):
 pages=pages or ([21] if kind=='questions' or n<=2 else [22] if n<=27 else [23] if n<=40 else [24])
 r=dict(id=f'physics-chapter-41-{kind}-{n}',parts=parts,reasoning=why+' Verification: '+parts[0]['explanation'],sourcePages=pages,assumptions=assumptions or ['Chapter free-electron density-of-states model; energies measured from the bottom of the band. Use SI constants and electron-volts consistently.'])
 if scope:r['scope']=scope
 r.update(kw);rows.append(r)
def f(E,EF,T):
 if T==0:return 1. if E<EF else 0. if E>EF else .5
 x=(E-EF)/(k*T)
 return exp(-x)/(1+exp(-x)) if x>0 else 1/(1+exp(x))
def dos(E):return D*sqrt(E)
def density(rho,M,z=1):return rho/M*NA*z
def ef(n):return A*n**(2/3)
def vf(E):return sqrt(2*E*e/me)
def simpson(fun,a,b,n=20000):
 dx=(b-a)/n;return dx/3*(fun(a)+fun(b)+sum((4 if i%2 else 2)*fun(a+i*dx) for i in range(1,n)))
def above_fraction(T,EF):
 a=k*T/EF
 above=a*simpson(lambda x:sqrt(1+a*x)/(exp(x)+1),0,50)
 belowholes=a*simpson(lambda x:sqrt(max(0,1-a*x))/(exp(x)+1),0,min(50,1/a))
 return above/(2/3-belowholes+above)
