# Readability fixes are applied only to prose; numeric derivations stay unchanged.
import re
prose_fixes={'AtT':'At T','AtE_F':'At E_F','Letx':'Let x','useρ':'use ρ','Useρ':'Use ρ','copperρ':'copper ρ','zincρ':'zinc ρ','givesρ':'gives ρ','andα':'and α','usep=':'use p=','soρ=':'so ρ=','doublesn':'doubles n','withkT':'with kT','tojoules':'to joules','pointsn→p':'points n→p','is(2/5)':'is (2/5)','n=p':'n = p'}
def readable(v):
 if isinstance(v,dict):return {key:readable(val) if key not in ('id','unit') else val for key,val in v.items()}
 if isinstance(v,list):return [readable(val) for val in v]
 if not isinstance(v,str):return v
 for a,b in prose_fixes.items():v=v.replace(a,b)
 v=re.sub(r'\b(the|The|from|with|at|At|and|each|is|as|of|to|by|all|level|Levels|height|valence|exactly|approximately|rounded|resulting|subtract|Subtract|contribute|contributes|have|are|only|over|about|near|than|between|for|Use|use|Problem|Table|Fig|convert|into|narrow|their)(?=[0-9.])',r'\1 ',v)
 v=re.sub(r'(?<=\d)(?=and\d)', ' ',v).replace('and2','and 2')
 return v
rows=readable(rows)
assert len(rows)==64 and len({r['id'] for r in rows})==64
for r in rows:
 for p in r['parts']:
  if p['type']=='numeric':assert math.isfinite(p['answer']) and (p['answer']==0 or p['tolerance']<abs(p['answer'])),(r['id'],p)
  else:assert p['answer'] in p['options'] and len(set(p['options']))==3
(HERE/'ch41.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
